import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"益","description":"周易集解 - 益","frontmatter":{"title":"益","description":"周易集解 - 益"},"headers":[],"relativePath":"zh/classics/jijie/042.md","filePath":"zh/classics/jijie/042.md"}'),l={name:"zh/classics/jijie/042.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="益" tabindex="-1">益 <a class="header-anchor" href="#益" aria-label="Permalink to “益”">​</a></h1><h2 id="益-1" tabindex="-1">益 <a class="header-anchor" href="#益-1" aria-label="Permalink to “益”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>益，利有攸往。利涉大川。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：損而不已必益，故受之以益。</p><p>崔憬曰：損終則弗損，益之，故言損而不已必益也。</p><p>虞翻曰：否上之初也。損上益下，其道大光。二利往坎應五，故利有攸往，中正有慶也。</p><p>虞翻曰：謂三失正。動成坎，體渙。坎為大川，故利涉大川。渙，舟檝象，木道乃行也。</p><p>鄭玄曰：陰陽之義，陽稱為君，陰稱為臣。今震一陽二陰，臣多於君矣。而四體巽之不應初，是天子損其所有以下諸侯也。人君之道，以益下為德，故謂之益也。震為雷，巽為風。雷動風行，二者相成，猶人君出教令，臣奉行之，故利有攸往。坎為大川，利涉大川矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：益，損上益下，民說無疆。自上下下，其道大光。利有攸往，中正有慶。利涉大川，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>蜀才曰：此本否卦。</p><p>案：乾之上九下處坤初。坤之初六，上升乾四。損上益下者也。</p><p>虞翻曰：上之初。坤為無疆，震為喜笑；以貴下賤，大得民，故｢說無疆｣矣。</p><p>虞翻曰：乾為大明，以乾照坤，故其道大光。或以上之三，離為大光矣。</p><p>虞翻曰：中正謂五，而二應之，乾為慶也。</p><p>虞翻曰：謂三動成渙。渙，舟檝象。巽木得水，故木道乃行也。</p><p>虞翻曰：震三動為離，離為日。巽為進，坤為疆。日與巽俱進，故日進無疆也。</p><p>虞翻曰：乾下之坤，震為出生，萬物出震，故天施地生。陽在初，坤為無方，日進無疆，故其益無方也。</p><p>虞翻曰：上來益三，四時象正。艮為時，震為行，與損同義，故｢與時偕行｣也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：風雷，益。君子以見善則遷，有過則改。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：君子，謂乾也。上之三，離為見。乾為善，坤為過。坤三進之乾四，故見善則遷。乾上之坤初，改坤之過。體復象，復以自知，故有過則改也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，利用為大作，元吉，無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：大作謂耕播耒耨之利，蓋取諸此也。坤為用，乾為大，震為作，故｢利用為大作｣。體復初得正，朋來無咎，故｢元吉，無咎｣。震，三月卦，日中星鳥，敬授民時，故以耕播也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：元吉，無咎，下不厚事也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：大作，為耕植也。處益之始，居震之初。震為稼穡，又為大作。益之大者，莫大耕植。故初九之利，｢利為大作｣。若能不厚勞於下民，不奪時於農畯，則｢大吉，無咎｣矣。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，或益之十朋之龜，弗克違，永貞吉。王用享於帝，吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：謂上從外來益三，故｢或益之｣。二得正遠應，利三之正，已得承之。坤數十，損兌為朋；謂三變離為龜，故｢十朋之龜｣。坤為永，上之三得正，故｢永貞吉｣。</p><p>虞翻曰：震稱帝。王謂五。否乾為王。體觀象。艮為宗廟。三乾折坤牛，體噬嗑食，故｢王用享於帝｣。得位，故吉。</p><p>乾寶曰：聖王先成其民，而後致力於神，故｢王用享於帝｣。在巽之宮，處震之象，是則蒼精之帝同始祖矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：或益之，自外來也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：乾上稱外，來益三也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，益之用凶事，無咎。有孚中行，告公用圭。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：坤為事，三多凶。上來益三得正。故益用凶事，無咎。</p><p>虞翻曰：公謂三，伏陽也。三動體坎，故｢有孚｣。震為中行，為告，位在中，故曰｢中行｣。三，公位。乾為圭，乾之三，故｢告公用圭｣。圭，桓圭也。</p><p>《九家易》曰：天子以尺二寸玄圭事天，以九寸事地也。上公執桓圭，九寸；諸侯執信圭，七寸；諸伯執躬圭，七寸；諸子執穀璧。五寸；諸男執蒲璧，五寸。五等諸侯，各執之以朝見天子也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：益用凶事，固有之矣。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：三上失正當變，是固有之。</p><p>乾寶曰：固有如桓文之徒，罪近篡弒，功實濟世。六三失位，而體姦邪。處震之動，懷巽之權，是矯命之士。爭奪之臣，桓文之爻也。故曰｢益之用凶事｣。在益之家，而居坤中，能保社稷，愛撫人民，故曰｢無咎｣。既乃中行，近仁，故曰｢有孚中行｣。然後俯列盟會，仰致錫命，故曰｢告公用圭｣。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，中行，告公從，利用為依遷國。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：中行正位在中，震為行，為從，故曰中行。公謂三，三上失位。四利三之正，已得以為實，故曰｢告公從｣矣。</p><p>虞翻曰：坤為國。遷，徙也。三動坤從，故利用為依遷國也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：告公從，以益志也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坎為志，三之上，有兩坎象，故｢以益志也｣。</p><p>崔憬曰：益其勤王之志也。居益之時，履當其位，與五近比，而四上公，得藩屏之寄，為依從之國，若周平王之東遷，晉鄭是從也。五為天子，益其忠志以勑之，故言｢中行告公從，利用為依遷國｣矣。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，有孚惠心，勿問，元吉。有孚惠我德。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：謂三上也。震為問。三上易位，三五體坎，已成既濟。坎為心。故｢有孚惠心，勿問，元吉｣。故《象》曰：｢勿問之矣。｣</p><p>虞翻曰：坤為我，乾為德，三之上體坎，為孚，故｢惠我德｣。《象》曰｢大得志也｣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：有孚惠心，勿問之矣。惠我德，大得志也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：居中履尊，當位有應。而損上之時，自一以損己為念。雖有孚於國，惠心及下，終不言以彰己功。故曰｢有孚惠心，勿問｣。問，猶言也。如是，則獲元吉，且為下所信，而懷己德，故曰｢有孚惠我德｣。君雖不言，人惠其德，則我大得志也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，莫益之，或擊之，立心勿恆，凶。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：莫，無也。自非上無益三者，唯初當無應，故｢莫益之｣矣。</p><p>虞翻曰：謂上不益初，則以剝滅乾。艮為手，故｢或擊之｣。</p><p>虞翻曰：上體巽，為進退，故｢勿恆｣。動成坎心，以陰乘陽，故｢立心勿恆，凶｣矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：莫益之，徧辭也。或擊之，自外來也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：徧，周匝也。三體剛凶，故至上應乃益之矣。</p><p>虞翻曰：外謂上。上來之三，故曰｢自外來也｣。</p>',85)])])}const f=e(l,[["render",p]]);export{b as __pageData,f as default};
